import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const SCHEMA = `
CREATE TABLE IF NOT EXISTS jobs (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL,
  input TEXT NOT NULL,
  steps INTEGER NOT NULL,
  fail_attempts INTEGER NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  completed INTEGER NOT NULL DEFAULT 0,
  result_output TEXT,
  error TEXT,
  available_at INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS jobs_status_seq ON jobs (status, seq);
CREATE TABLE IF NOT EXISTS idempotency (
  key TEXT PRIMARY KEY,
  fingerprint TEXT NOT NULL,
  job_id TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS heartbeats (
  name TEXT PRIMARY KEY,
  at INTEGER NOT NULL
);
`;

/** Opens the SQLite database shared by the server and worker processes, creating the schema if needed. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  db.exec(SCHEMA);
  return db;
}

/** Runs `fn` inside a write transaction. Writers take the lock up front so read-then-write is atomic across processes. */
export function transaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    db.exec('COMMIT');
    return result;
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}
import type { DatabaseSync } from 'node:sqlite';

/** Number of processing attempts before a transiently failing job is marked failed. */
export const MAX_ATTEMPTS = 3;
/** Delay before a failed attempt is retried. Must lie between 250 ms and 2 s. */
export const RETRY_DELAY_MS = 500;
/** Simulated duration of one processing step. */
export const STEP_MS = 100;

/** A row of the `jobs` table, as stored. */
export interface JobRow {
  seq: number;
  id: string;
  status: string;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  result_output: string | null;
  error: string | null;
  available_at: number;
  created_at: string;
  updated_at: string;
}

/** The public JSON shape of a job. */
export interface Job {
  id: string;
  status: string;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export function toJob(r: JobRow): Job {
  return {
    id: r.id,
    status: r.status,
    input: r.input,
    steps: r.steps,
    failAttempts: r.fail_attempts,
    attempts: r.attempts,
    progress: { completed: r.completed, total: r.steps },
    result: r.status === 'completed' && r.result_output !== null ? { output: r.result_output } : null,
    error: r.status === 'failed' ? r.error : null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

export function getJobRow(db: DatabaseSync, id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
}
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, transaction } from './db.ts';
import { getJobRow, toJob, type JobRow } from './jobs.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

/** The worker counts as up if its heartbeat is at most this old. */
const WORKER_STALE_MS = 3_000;
/** Largest request body accepted. Input is at most 1000 characters, so this is generous. */
const MAX_BODY_BYTES = 64 * 1024;
const JSON_CONTENT_TYPE = /^application\/json(\s*;.*)?$/i;
const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;
const MAX_INPUT_LENGTH = 1000;

interface FieldError {
  field: string;
  message: string;
}

class ApiError extends Error {
  status: number;
  code: string;
  fields: FieldError[] | undefined;
  allow: string | undefined;

  constructor(status: number, code: string, message: string, fields?: FieldError[], allow?: string) {
    super(message);
    this.status = status;
    this.code = code;
    this.fields = fields;
    this.allow = allow;
  }
}

function invalid(fields: FieldError[]): ApiError {
  return new ApiError(400, 'invalid_request', 'The request is invalid.', fields);
}

function methodNotAllowed(allowed: string[]): ApiError {
  return new ApiError(405, 'method_not_allowed', `Method not allowed. Use ${allowed.join(', ')}.`, undefined, allowed.join(', '));
}

function sendJson(res: ServerResponse, status: number, body: unknown, extraHeaders: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...extraHeaders });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, err: ApiError): void {
  const error: Record<string, unknown> = { code: err.code, message: err.message };
  if (err.fields) error.fields = err.fields;
  sendJson(res, err.status, { error }, err.allow ? { allow: err.allow } : {});
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => {
      if (tooLarge) reject(invalid([{ field: 'body', message: `Body must be at most ${MAX_BODY_BYTES} bytes.` }]));
      else resolve(Buffer.concat(chunks).toString('utf8'));
    });
    req.on('error', reject);
  });
}

interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
  key: string | undefined;
}

/** Checks the request headers and body, returning the submission with defaults applied. Throws invalid_request listing every bad field. */
function parseSubmission(req: IncomingMessage, raw: string): Submission {
  const errors: FieldError[] = [];

  // A repeated header is joined, so it fails the key pattern rather than being silently truncated.
  const rawKey = req.headers['idempotency-key'];
  const key = Array.isArray(rawKey) ? rawKey.join(',') : rawKey;
  if (key !== undefined && !IDEMPOTENCY_KEY.test(key)) {
    errors.push({ field: 'Idempotency-Key', message: 'Must be 1–128 characters of letters, digits, "_" or "-".' });
  }

  let input = '';
  let steps = 5;
  let failAttempts = 0;
  const rawType = req.headers['content-type'];
  const contentType = Array.isArray(rawType) ? rawType.join(',') : rawType;
  if (!contentType || !JSON_CONTENT_TYPE.test(contentType)) {
    errors.push({ field: 'body', message: 'Content-Type must be application/json.' });
  } else {
    let parsed: unknown;
    let parsedOk = false;
    try {
      parsed = JSON.parse(raw);
      parsedOk = true;
    } catch {
      errors.push({ field: 'body', message: 'Body must be valid JSON.' });
    }
    if (parsedOk) {
      if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
        errors.push({ field: 'body', message: 'Body must be a JSON object.' });
      } else {
        const obj = parsed as Record<string, unknown>;
        const allowed = new Set(['input', 'steps', 'failAttempts']);
        for (const name of Object.keys(obj)) {
          if (!allowed.has(name)) errors.push({ field: name, message: 'Unknown field.' });
        }

        if (!('input' in obj)) {
          errors.push({ field: 'input', message: 'Required.' });
        } else if (typeof obj.input !== 'string') {
          errors.push({ field: 'input', message: 'Must be a string.' });
        } else if (obj.input.length < 1 || obj.input.length > MAX_INPUT_LENGTH) {
          errors.push({ field: 'input', message: `Must be 1–${MAX_INPUT_LENGTH} characters.` });
        } else if (obj.input.trim() === '') {
          errors.push({ field: 'input', message: 'Must not be only whitespace.' });
        } else {
          input = obj.input;
        }

        const readInt = (name: 'steps' | 'failAttempts', min: number, max: number, fallback: number): number => {
          if (!(name in obj)) return fallback;
          const value = obj[name];
          if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
            errors.push({ field: name, message: `Must be an integer from ${min} to ${max}.` });
            return fallback;
          }
          return value;
        };
        steps = readInt('steps', 1, 20, 5);
        failAttempts = readInt('failAttempts', 0, 5, 0);
      }
    }
  }

  if (errors.length > 0) throw invalid(errors);
  return { input, steps, failAttempts, key };
}

function workerUp(): boolean {
  const row = db.prepare("SELECT at FROM heartbeats WHERE name = 'worker'").get() as { at: number } | undefined;
  return row !== undefined && Date.now() - row.at <= WORKER_STALE_MS;
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const sub = parseSubmission(req, await readBody(req));
  const fingerprint = JSON.stringify([sub.input, sub.steps, sub.failAttempts]);
  const now = new Date().toISOString();

  const outcome = transaction(db, () => {
    if (sub.key !== undefined) {
      const prior = db.prepare('SELECT fingerprint, job_id FROM idempotency WHERE key = ?').get(sub.key) as
        | { fingerprint: string; job_id: string }
        | undefined;
      if (prior) {
        if (prior.fingerprint !== fingerprint) {
          throw new ApiError(409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
        }
        const row = getJobRow(db, prior.job_id);
        if (!row) throw new Error(`idempotency key ${sub.key} points at missing job ${prior.job_id}`);
        return { replay: true, row };
      }
    }
    const id = randomUUID();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, result_output, error, available_at, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, ?)`,
    ).run(id, sub.input, sub.steps, sub.failAttempts, Date.now(), now, now);
    if (sub.key !== undefined) {
      db.prepare('INSERT INTO idempotency (key, fingerprint, job_id) VALUES (?, ?, ?)').run(sub.key, fingerprint, id);
    }
    const row = getJobRow(db, id);
    if (!row) throw new Error(`job ${id} missing right after insert`);
    return { replay: false, row };
  });

  sendJson(res, outcome.replay ? 200 : 201, toJob(outcome.row));
}

function listJobs(res: ServerResponse): void {
  const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
  sendJson(res, 200, { jobs: rows.map(toJob) });
}

function getJob(res: ServerResponse, id: string): void {
  const row = getJobRow(db, id);
  if (!row) throw new ApiError(404, 'not_found', 'No job with that id.');
  sendJson(res, 200, toJob(row));
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/health') {
    if (method !== 'GET') throw methodNotAllowed(['GET']);
    sendJson(res, 200, { status: 'ok', worker: workerUp() ? 'up' : 'down' });
    return;
  }
  if (pathname === '/') {
    if (method !== 'GET') throw methodNotAllowed(['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return listJobs(res);
    if (method === 'POST') return createJob(req, res);
    throw methodNotAllowed(['GET', 'POST']);
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') throw methodNotAllowed(['GET']);
    return getJob(res, match[1]!);
  }
  throw new ApiError(404, 'not_found', 'No such route.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((e: unknown) => {
    if (res.headersSent) {
      res.end();
      return;
    }
    if (e instanceof ApiError) {
      sendError(res, e);
      return;
    }
    console.error('unexpected error:', e);
    sendJson(res, 500, { error: { code: 'internal_error', message: 'Internal error.' } });
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    server.close();
    server.closeAllConnections();
    db.close();
    process.exit(0);
  });
}
import { setTimeout as sleep } from 'node:timers/promises';
import type { DatabaseSync } from 'node:sqlite';
import { openDatabase, transaction } from './db.ts';
import { getJobRow, MAX_ATTEMPTS, RETRY_DELAY_MS, STEP_MS, type JobRow } from './jobs.ts';

const db: DatabaseSync = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

const IDLE_POLL_MS = 200;
const HEARTBEAT_MS = 500;
let lastBeat = 0;

function heartbeat(force = false): void {
  const now = Date.now();
  if (!force && now - lastBeat < HEARTBEAT_MS) return;
  lastBeat = now;
  db.prepare(
    "INSERT INTO heartbeats (name, at) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at = excluded.at",
  ).run(now);
}

/**
 * Jobs still marked running belong to a previous worker that died mid-attempt. Only one worker
 * runs at a time, so they are put back in the queue and processed again.
 */
function recoverInterrupted(): void {
  db.prepare(
    "UPDATE jobs SET status = 'queued', completed = 0, available_at = ?, updated_at = ? WHERE status = 'running'",
  ).run(Date.now(), new Date().toISOString());
}

/** Atomically takes the oldest runnable queued job and starts an attempt on it. */
function claimNext(): JobRow | undefined {
  return transaction(db, () => {
    const next = db
      .prepare("SELECT id FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1")
      .get(Date.now()) as { id: string } | undefined;
    if (!next) return undefined;
    db.prepare(
      "UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ? WHERE id = ? AND status = 'queued'",
    ).run(new Date().toISOString(), next.id);
    return getJobRow(db, next.id);
  });
}

/** Records that an attempt was cut short by shutdown. The job goes back to the queue and the attempt is not retried in this process. */
function requeueForShutdown(id: string): void {
  db.prepare(
    "UPDATE jobs SET status = 'queued', completed = 0, available_at = ?, updated_at = ? WHERE id = ? AND status = 'running'",
  ).run(Date.now(), new Date().toISOString(), id);
}

function failAttempt(id: string, attempt: number): void {
  const now = new Date().toISOString();
  if (attempt < MAX_ATTEMPTS) {
    db.prepare(
      "UPDATE jobs SET status = 'queued', completed = 0, available_at = ?, updated_at = ? WHERE id = ? AND status = 'running'",
    ).run(Date.now() + RETRY_DELAY_MS, now, id);
  } else {
    db.prepare(
      "UPDATE jobs SET status = 'failed', completed = 0, result_output = NULL, error = 'transient failure', updated_at = ? WHERE id = ? AND status = 'running'",
    ).run(now, id);
  }
}

function setProgress(id: string, completed: number): void {
  db.prepare("UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ? AND status = 'running'").run(
    completed,
    new Date().toISOString(),
    id,
  );
}

function complete(job: JobRow): void {
  db.prepare(
    "UPDATE jobs SET status = 'completed', completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE id = ? AND status = 'running'",
  ).run(job.input.toUpperCase(), new Date().toISOString(), job.id);
}

async function processJob(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  // Simulated transient failure: the attempt fails at its first step, before any progress.
  if (attempt <= job.fail_attempts) {
    await sleep(STEP_MS);
    if (stopping) return requeueForShutdown(job.id);
    failAttempt(job.id, attempt);
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return requeueForShutdown(job.id);
    setProgress(job.id, step);
  }
  complete(job);
}

async function main(): Promise<void> {
  heartbeat(true);
  recoverInterrupted();
  console.log('worker started');

  while (!stopping) {
    try {
      heartbeat();
      const job = claimNext();
      if (job) {
        await processJob(job);
      } else {
        await sleep(IDLE_POLL_MS);
      }
    } catch (e) {
      console.error('worker error:', e);
      await sleep(IDLE_POLL_MS);
    }
  }

  db.prepare("DELETE FROM heartbeats WHERE name = 'worker'").run();
  db.close();
  console.log('worker stopped');
}

main().catch((e: unknown) => {
  console.error('worker failed:', e);
  process.exit(1);
});
