<body>
  <h1>Job tracker</h1>

  <form data-testid="job-form" id="job-form" novalidate>
    <label>Input
      <input data-testid="job-input" name="input" type="text" autocomplete="off">
    </label>
    <label>Steps
      <input data-testid="job-steps" name="steps" type="number" step="1" value="5">
    </label>
    <label>Fail attempts
      <input data-testid="job-fail-attempts" name="failAttempts" type="number" step="1" value="0">
    </label>
    <button data-testid="job-submit" type="submit">Submit job</button>
  </form>

  <div data-testid="form-error" role="alert"></div>

  <ul data-testid="job-list" id="job-list"></ul>

  <script>
    (function () {
      var form = document.getElementById('job-form');
      var inputField = form.querySelector('[data-testid="job-input"]');
      var stepsField = form.querySelector('[data-testid="job-steps"]');
      var failField = form.querySelector('[data-testid="job-fail-attempts"]');
      var submitButton = form.querySelector('[data-testid="job-submit"]');
      var errorRegion = document.querySelector('[data-testid="form-error"]');
      var list = document.getElementById('job-list');

      // Numeric fields are sent as numbers. Anything that is not a number is sent as typed so the API rejects it.
      function numberOrRaw(text) {
        var trimmed = text.trim();
        if (trimmed === '') return undefined;
        var n = Number(trimmed);
        return Number.isNaN(n) ? trimmed : n;
      }

      function showError(lines) {
        errorRegion.textContent = lines.join('\n');
      }

      function describeRejection(body, status) {
        var error = body && body.error;
        if (!error) return 'Request failed with status ' + status + '.';
        var lines = [error.message || 'Request failed.'];
        if (Array.isArray(error.fields)) {
          error.fields.forEach(function (f) {
            lines.push(f.field + ': ' + f.message);
          });
        }
        return lines;
      }

      form.addEventListener('submit', function (event) {
        event.preventDefault();
        var payload = { input: inputField.value };
        var steps = numberOrRaw(stepsField.value);
        var failAttempts = numberOrRaw(failField.value);
        if (steps !== undefined) payload.steps = steps;
        if (failAttempts !== undefined) payload.failAttempts = failAttempts;

        submitButton.disabled = true;
        fetch('/api/jobs', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify(payload),
        })
          .then(function (res) {
            return res.json().catch(function () { return null; }).then(function (body) {
              if (res.status === 200 || res.status === 201) {
                showError([]);
                inputField.value = '';
                refresh();
                return;
              }
              var lines = describeRejection(body, res.status);
              showError(Array.isArray(lines) ? lines : [lines]);
            });
          })
          .catch(function () {
            showError(['Could not reach the server. Try again.']);
          })
          .then(function () {
            submitButton.disabled = false;
          });
      });

      function renderJob(job) {
        var item = document.createElement('li');
        item.setAttribute('data-testid', 'job-item');
        item.setAttribute('data-job-id', job.id);

        var input = document.createElement('div');
        input.className = 'job-input';
        input.textContent = job.input;

        var id = document.createElement('div');
        id.className = 'job-id';
        id.textContent = job.id;

        var meta = document.createElement('div');
        meta.className = 'job-meta';

        var status = document.createElement('span');
        status.setAttribute('data-testid', 'job-status');
        status.textContent = job.status;

        var progress = document.createElement('span');
        progress.setAttribute('data-testid', 'job-progress');
        progress.textContent = job.progress.completed + '/' + job.progress.total;

        var result = document.createElement('span');
        result.setAttribute('data-testid', 'job-result');
        if (job.status === 'completed' && job.result) result.textContent = job.result.output;
        else if (job.status === 'failed') result.textContent = job.error || '';
        else result.textContent = '';

        meta.appendChild(status);
        meta.appendChild(progress);
        meta.appendChild(result);
        item.appendChild(input);
        item.appendChild(meta);
        item.appendChild(id);
        return item;
      }

      function refresh() {
        return fetch('/api/jobs', { cache: 'no-store' })
          .then(function (res) { return res.ok ? res.json() : null; })
          .then(function (body) {
            if (!body || !Array.isArray(body.jobs)) return;
            var fragment = document.createDocumentFragment();
            body.jobs.forEach(function (job) { fragment.appendChild(renderJob(job)); });
            list.replaceChildren(fragment);
          })
          .catch(function () { /* try again on the next tick */ });
      }

      refresh();
      setInterval(refresh, 1000);
    })();
